#### Merton Model ####import numpy as npfrom scipy import statsfrom quant_finance.options.black_scholes_pricing import black_scholes_price"""Notation:    V_t: Current market value of the firm's assets (`asset_value`)    D:   Face value of debt payable at maturity (`debt_face_value`)    r:   Continuously compounded risk-free rate (`risk_free_rate`)    σ_V: Volatility of the firm's assets (`asset_volatility`)    τ:   Remaining time to debt maturity (`time_to_maturity`)    E_t: Current market value of equity (`equity_value`)    B_t: Current market value of risky debt (`debt_value`)"""#calculate equity value under Merton modeldef merton_equity_value(    asset_value,    debt_face_value,    risk_free_rate,    asset_volatility,    time_to_maturity,):        equity_value = black_scholes_price(        S=asset_value,        K=debt_face_value,        r=risk_free_rate,        sigma=asset_volatility,        T=time_to_maturity,        q=0.0,        option_type="call",    )    return equity_value#calculate "risky debt"def merton_debt_value(    asset_value,    debt_face_value,    risk_free_rate,    asset_volatility,    time_to_maturity,):    equity_value = merton_equity_value(        asset_value=asset_value,        debt_face_value=debt_face_value,        risk_free_rate=risk_free_rate,        asset_volatility=asset_volatility,        time_to_maturity=time_to_maturity,    )        return asset_value - equity_value#calculate risk-neutral distance to defaultdef distance_to_default(    asset_value,    debt_face_value,    risk_free_rate,    asset_volatility,    time_to_maturity,):    dd = (np.log(asset_value / debt_face_value)        + (risk_free_rate - 0.5 * asset_volatility**2) * time_to_maturity        ) / (asset_volatility * np.sqrt(time_to_maturity))    return dd#calculate probability of defaultdef merton_probability_of_default(    asset_value,    debt_face_value,    risk_free_rate,    asset_volatility,    time_to_maturity,):        dd =distance_to_default(        asset_value=asset_value,        debt_face_value=debt_face_value,        risk_free_rate=risk_free_rate,        asset_volatility=asset_volatility,        time_to_maturity=time_to_maturity        )        pd = stats.norm.cdf(-dd)        return pd